/* MIT. Bounded personal classic companion. Persistent numbers are integers. */
static int homun_alive50(const Combat*g){return g->hp>0&&job_parent52(g->jobId)==20&&g->persistent50.homunType&&!g->persistent50.homunResting&&g->persistent50.homunHP;}
static int homun_family50(const Combat*g){return g->persistent50.homunType?(g->persistent50.homunType-6001)%4:-1;}
static unsigned homun_random50(Combat*g,const unsigned range[2]){return range[0]+combat_random(g)%(range[1]-range[0]+1);}
static int homun_stat50(const Combat*g,int stat){const ClassPersistent50*p=&g->persistent50;int v=p->homunStats[stat],r=p->homunSkills[14];if(stat==0&&r)v+=1+2*(r/3)+r/4;if(stat==3&&r)v+=1+r/2+r/4+r/5;if(g->class50.homunBuffUntil[3]>g->time){if(stat==2)v+=30*p->homunSkills[3];if(stat==3)v+=20*p->homunSkills[3];}return v;}
static int homun_buff50(const Combat*g,int skill){return g->class50.homunBuffUntil[skill]>g->time?g->persistent50.homunSkills[skill]:0;}
static const unsigned*homun_tree50(const Combat*g,int skill){for(unsigned i=0;i<sizeof(homunTree50)/sizeof(*homunTree50);i++)if(homunTree50[i][0]==g->persistent50.homunType&&homunTree50[i][1]==(unsigned)skill)return homunTree50[i];return NULL;}
static void homun_place50(Combat*g){g->class50.homunX=g->x;g->class50.homunY=g->y;g->class50.homunMap=g->mapId;g->class50.homunTarget=-1;g->class50.homunFaceY=1;g->class50.homunHungerAt=g->time+60;g->class50.homunRegenAt=g->time+6;g->class50.homunSPRegenAt=g->time+8;}
static void homun_create50(Combat*g){ClassPersistent50*p=&g->persistent50;int n=combat_random(g)%8;const HomunData50*d=&homunData50[n];p->homunType=d->id;p->homunLevel=1;p->homunHunger=32;p->homunIntimacy=2100;p->homunMaxHP=d->base[0];p->homunMaxSP=d->base[1];p->homunHP=10;p->homunSP=0;for(int i=0;i<6;i++)p->homunStats[i]=d->base[i+2];homun_place50(g);}
static void homun_gain50(Combat*g,unsigned exp){ClassPersistent50*p=&g->persistent50;if(!homun_alive50(g)||p->homunLevel>=99)return;p->homunExp+=exp;const HomunData50*d=&homunData50[p->homunType-6001];while(p->homunLevel<99&&p->homunExp>homunEXP50[p->homunLevel-1]){p->homunExp-=homunEXP50[p->homunLevel-1];p->homunLevel++;if(p->homunLevel%3==0)p->homunPoints++;p->homunMaxHP+=homun_random50(g,d->growth[0]);p->homunMaxSP+=homun_random50(g,d->growth[1]);for(int i=0;i<6;i++)p->homunStats[i]+=homun_random50(g,d->growth[i+2])/10;p->homunHP=homun_maxhp50(p);p->homunSP=homun_maxsp50(p);}if(p->homunLevel==99)p->homunExp=0;}
static int homun_learn50(Combat*g,int row){ClassPersistent50*p=&g->persistent50;int family=homun_family50(g),skill=family*4+row;if(family<0||row<0||row>=4||!p->homunPoints)return 0;const unsigned*t=homun_tree50(g,skill);if(!t||p->homunSkills[skill]>=t[2]||p->homunIntimacy<t[13])return 0;for(int i=3;i<13;i+=2)if(t[i]!=65535&&p->homunSkills[t[i]]<t[i+1])return 0;p->homunSkills[skill]++;p->homunPoints--;combat_message(g,"Learned %s rank %d.",homunSkill50[skill].name,p->homunSkills[skill]);return 1;}
static int homun_feed50(Combat*g){if(!homun_alive50(g))return 0;ClassPersistent50*p=&g->persistent50;int food=item_source50(homunData50[p->homunType-6001].food);if(!inventory_count(g,food)){combat_message(g,"Need %s to feed your Homunculus.",itemDefs[food].name);return 0;}--*inventory_stack(g,food);int gain=p->homunHunger>=91?-50:p->homunHunger>=76?-5:p->homunHunger>=26?75:p->homunHunger>=11?100:50;p->homunIntimacy=(int)p->homunIntimacy+gain>0?p->homunIntimacy+gain:0;if(p->homunIntimacy>100000)p->homunIntimacy=100000;p->homunHunger+=10;if(p->homunHunger>100)p->homunHunger=100;if(!p->homunIntimacy){unsigned falcon=p->falcon,copy=p->copySkill,rank=p->copyRank;memset(p,0,sizeof(*p));p->falcon=falcon;p->copySkill=copy;p->copyRank=rank;}combat_message(g,"Fed your Homunculus.");return 1;}
static int homun_evolve50(Combat*g){ClassPersistent50*p=&g->persistent50;if(!homun_alive50(g)||p->homunType>=6009||p->homunIntimacy<91000)return 0;int stone=item_source50(12040);if(!inventory_count(g,stone)){combat_message(g,"Evolution needs a Stone of Sage.");return 0;}--*inventory_stack(g,stone);const HomunData50*d=&homunData50[p->homunType-6001];p->homunType=d->evolution;p->homunMaxHP+=homun_random50(g,d->evo[0]);p->homunMaxSP+=homun_random50(g,d->evo[1]);for(int i=0;i<6;i++)p->homunStats[i]+=homun_random50(g,d->evo[i+2]);p->homunIntimacy=500;combat_message(g,"Your Homunculus evolved.");return 1;}
static void homun_execute50(Combat*g,unsigned id,int rank){ClassPersistent50*p=&g->persistent50;if(id==250){if(!p->homunType)homun_create50(g);else{p->homunResting=0;homun_place50(g);}}else if(id==251)p->homunResting=1;else if(id==252){p->homunHP=homun_maxhp50(p)*rank*20/100;homun_place50(g);}}
static int homun_physical50(Combat*g,CombatMob*m,int ratio){int strength=homun_stat50(g,0),dex=homun_stat50(g,4),level=g->persistent50.homunLevel;int lo=dex,hi=strength+level;if(lo>hi)lo=hi;int weapon=lo+(hi>lo?combat_random(g)%(hi-lo):0);if(homun_buff50(g,3)){int intel=homun_stat50(g,3);return intel+intel/5*(intel/5);}int base=strength+strength/10*(strength/10)+dex/5+homun_stat50(g,5)/5;int rate=100;if(homun_buff50(g,7))rate+=20+10*homun_buff50(g,7);if(homun_buff50(g,9))rate+=5+5*homun_buff50(g,9);return combat_reduce48((base+weapon)*ratio/100*rate/100,combat_enemy_defense(m),mobStunVit[m->kind]);}
static void homun_hit50(Combat*g,int target,int damage,int hits){int old=g->fxSkill,oldDeal=g->class50.homunDealing;g->fxSkill=0;g->class50.homunDealing=1;skill_hit_ex(g,target,damage,0,hits);g->class50.homunDealing=oldDeal;g->fxSkill=old;}
static int homun_skill50(Combat*g,int row){ClassPersistent50*p=&g->persistent50;int skill=homun_family50(g)*4+row;if(!homun_alive50(g)||row<0||row>3)return 0;int rank=p->homunSkills[skill];if(!rank||skill==2||skill==6||skill==14)return 0;const HomunSkill50*d=&homunSkill50[skill];if(g->class50.homunCooldown[skill]>g->time||p->homunSP<d->sp[rank-1])return 0;int target=g->target;float x=g->class50.homunX,y=g->class50.homunY;
 if(skill==8||skill==11||skill==12){if(!combat_valid_target(g,target)||!class_in_area50(g,&g->mobs[target],x,y,skill==12?72:16))return 0;}
 int red=item_source50(545);if(skill==0&&(!inventory_count(g,red)||p->homunHP>=homun_maxhp50(p)))return 0;
 if(skill==11&&p->homunIntimacy<=200||skill==15&&p->homunIntimacy<45000)return 0;
 p->homunSP-=d->sp[rank-1];g->class50.homunFx=skill+1;g->class50.homunFxAt=g->time;float block=d->block[rank-1]>d->delay[rank-1]?d->block[rank-1]:d->delay[rank-1];g->class50.homunCooldown[skill]=g->time+block/1000.f;
 if(skill==0){--*inventory_stack(g,red);p->homunHP+=(p->homunLevel+homun_stat50(g,3))/8*(4+8*rank);if(p->homunHP>homun_maxhp50(p))p->homunHP=homun_maxhp50(p);}
 else if(skill==4){if(class_chance50(g,20*rank,100)){float tx=g->x,ty=g->y;g->x=x;g->y=y;g->class50.homunX=tx;g->class50.homunY=ty;for(int i=0;i<MOB_COUNT;i++)if(g->mobs[i].aggro)g->mobs[i].class50.companionTarget=1;}}
 else if(skill==8){CombatMob*m=&g->mobs[target];int hits=rank==1?1:rank<5?2:3;homun_hit50(g,target,homun_physical50(g,m,110+110*rank),hits);}
 else if(skill==11){unsigned damage=p->homunIntimacy*rank;p->homunIntimacy=200;homun_hit50(g,target,damage,1);}
 else if(skill==12){int intel=homun_stat50(g,3),element=1+combat_random(g)%4;int power=intel+(intel/5)*(intel/5);homun_hit50(g,target,combat_magic_def48(&g->mobs[target],power*rank*class_attack_rate48(g,&g->mobs[target],element)/100,rank),rank);}
 else if(skill==13){static const unsigned char chance[5][2]={{20,50},{50,60},{25,75},{60,64},{34,67}};int roll=combat_random(g)%100,healRank=1+combat_random(g)%rank,amount=(p->homunLevel+homun_stat50(g,3))/8*(4+8*healRank);if(roll<chance[rank-1][0]||(!combat_valid_target(g,target)&&roll>=chance[rank-1][1])){p->homunHP+=amount;if(p->homunHP>homun_maxhp50(p))p->homunHP=homun_maxhp50(p);}else if(roll<chance[rank-1][1]){g->hp+=amount;if(g->hp>g->maxhp)g->hp=g->maxhp;}else{CombatMob*m=&g->mobs[target];m->hp+=amount;if(m->hp>combat_mob_max(m))m->hp=combat_mob_max(m);}}
 else if(skill==15){p->homunIntimacy=200;for(int i=0;i<MOB_COUNT;i++)if(class_in_area50(g,&g->mobs[i],x,y,36))homun_hit50(g,i,homun_maxhp50(p)*(50+50*rank)/100,1);p->homunHP=0;}
 else{g->class50.homunBuffUntil[skill]=g->time+d->duration[rank-1]/1000.f;if(skill==3){p->homunHP=homun_maxhp50(p);p->homunSP=homun_maxsp50(p);}}
 combat_message(g,"%s rank %d.",d->name,rank);return 1;
}
static void homun_tick50(Combat*g,float dt){
 if(!homun_alive50(g))return;ClassPersistent50*p=&g->persistent50;ClassTransient50*t=&g->class50;const HomunData50*d=&homunData50[p->homunType-6001];
 if(t->homunMap!=g->mapId||t->homunX<8||t->homunY<8)homun_place50(g);t->homunMoving=0;
 if(t->homunBuffUntil[3]>0&&t->homunBuffUntil[3]<=g->time){t->homunBuffUntil[3]=0;p->homunHP=p->homunSP=10;}
 if(g->time>=t->homunHungerAt){t->homunHungerAt+=d->hungerMS/1000.f;if(p->homunHunger)p->homunHunger--;else if(p->homunIntimacy>100)p->homunIntimacy-=100;else{unsigned falcon=p->falcon;memset(p,0,sizeof(*p));p->falcon=falcon;combat_message(g,"Your starving Homunculus left.");return;}}
 int target=t->homunHold?-1:g->target;if(!combat_valid_target(g,target))target=-1;t->homunTarget=target;
 float tx=target>=0?g->mobs[target].x:g->x,ty=target>=0?g->mobs[target].y:g->y,dx=tx-t->homunX,dy=ty-t->homunY,distance=sqrtf(dx*dx+dy*dy),reach=target>=0?16:24;
 if(distance>reach){combat_face(&t->homunFaceX,&t->homunFaceY,dx,dy);float step=fminf(combat_walk_speed(g)*dt,distance-reach);t->homunMoving=combat_move(g,&t->homunX,&t->homunY,t->homunX+dx/distance*step,t->homunY+dy/distance*step);}
 else if(target>=0&&g->time>=t->homunAttackAt&&class_reachable50(g,t->homunX,t->homunY,tx,ty)){CombatMob*m=&g->mobs[target];combat_face(&t->homunFaceX,&t->homunFaceY,dx,dy);if(class_chance50(g,combat_hit_rate(p->homunLevel+homun_stat50(g,4),combat_mob_flee(m)),100)){int damage=homun_physical50(g,m,100);homun_hit50(g,target,damage,1);if(m->hp>0){m->class50.companionTarget=1;m->aggro=1;}int blood=homun_buff50(g,7);if(blood&&class_chance50(g,3*blood,100)){p->homunHP+=damage/5;if(p->homunHP>homun_maxhp50(p))p->homunHP=homun_maxhp50(p);}}else combat_miss(g,m->x,m->y);int motion=(1000-4*homun_stat50(g,1)-homun_stat50(g,4))*d->motion/1000;if(homun_buff50(g,9))motion=motion*(1000-30*homun_buff50(g,9))/1000;if(motion<100)motion=100;t->homunLastAttack=g->time;t->homunAttackAt=g->time+motion/1000.f;}
 if(t->homunMoving)t->homunRegenAt+=dt;
 if(g->time>=t->homunRegenAt){p->homunHP+=1+homun_stat50(g,2)/5+homun_maxhp50(p)/200;t->homunRegenAt+=6.f*100/(100+5*p->homunSkills[6]);if(p->homunHP>homun_maxhp50(p))p->homunHP=homun_maxhp50(p);}
 if(g->time>=t->homunSPRegenAt){int intel=homun_stat50(g,3);p->homunSP+=1+intel/6+homun_maxsp50(p)/100+(intel>=120?4+(intel-120)/2:0);t->homunSPRegenAt+=8.f*100/(100+3*p->homunSkills[2]);if(p->homunSP>homun_maxsp50(p))p->homunSP=homun_maxsp50(p);}
}
static int class_companion_menu50(Combat*g,int choice){
 if(g->utilityMenu==501){if(job_parent52(g->jobId)!=14||!class_rank50(g,165))return 0;if(choice){g->persistent50.falcon=0;return 1;}if(g->persistent50.falcon)return 0;if(g->zeny<2500){combat_message(g,"Falcon hire costs 2500 Zeny.");return 0;}g->zeny-=2500;g->persistent50.falcon=1;return 1;}
 if(job_parent52(g->jobId)!=20)return 0;if(choice==0)return homun_feed50(g);if(choice==1){g->class50.homunHold=!g->class50.homunHold;return 1;}if(choice==2)return homun_evolve50(g);
 if(choice==3){int best=-1;float nearest=24;for(int n=0;n<CLASS_SUMMONS50;n++){ClassSummon50*s=&g->summons50[n];float d=combat_dist(g->x,g->y,s->x,s->y);if(s->kind==5&&s->hp>0&&s->until>g->time&&!s->triggered&&d<nearest){nearest=d;best=n;}}if(best<0)return 0;g->summons50[best].triggered=1;g->summons50[best].next=g->time+5;return 1;}
 return homun_skill50(g,choice-4);
}
static int class_mob_companion50(Combat*g,int i,float dt){
 CombatMob*m=&g->mobs[i];int which=m->class50.companionTarget;if(which==CLASS_SUMMONS50+2)return mercenary_enemy180(g,i,dt);if(!which)return 0;float x,y;int defense=0,soft=0,flee=0;unsigned*homHP=NULL;ClassSummon50*s=NULL;
 if(which==1){if(!homun_alive50(g)){m->class50.companionTarget=0;return 0;}x=g->class50.homunX;y=g->class50.homunY;homHP=&g->persistent50.homunHP;defense=g->persistent50.homunLevel/10+homun_stat50(g,2)/5+4*g->persistent50.homunSkills[6]+2*homun_buff50(g,5);soft=homun_stat50(g,2);flee=g->persistent50.homunLevel+homun_stat50(g,1)+(homun_buff50(g,10)?10+10*homun_buff50(g,10):0);}
 else{int n=which-2;if(n<0||n>=CLASS_SUMMONS50){m->class50.companionTarget=0;return 0;}s=&g->summons50[n];if(s->until<=g->time||s->map!=g->mapId||s->hp<=0){m->class50.companionTarget=0;return 0;}x=s->x;y=s->y;defense=summonData50[s->kind][5];}
 float dx=x-m->x,dy=y-m->y,distance=sqrtf(dx*dx+dy*dy);combat_face(&m->faceX,&m->faceY,dx,dy);m->aggro=1;m->sleeping=0;
 if(distance>mobRange43[m->kind]){if(m->class50.rootUntil<=g->time&&m->class50.closeUntil<=g->time)m->moving=combat_move(g,&m->x,&m->y,m->x+m->faceX*mobSpecs[m->kind].speed*dt,m->y+m->faceY*mobSpecs[m->kind].speed*dt);return 1;}
 if(m->cooldown>0||!class_reachable50(g,m->x,m->y,x,y))return 1;m->attackAt=g->time;m->cooldown=mobSpecs[m->kind].delay;
 if(!class_chance50(g,combat_hit_rate(mobSourceLevel[m->kind]+mobSourceDex[m->kind],flee),100)){combat_miss(g,x,y);return 1;}
 const MobSpec*d=&mobSpecs[m->kind];int damage=combat_reduce48(d->amin+combat_random(g)%(d->amax-d->amin+1),defense,soft);combat_number(g,x,y,damage,1,0);combat_hit_sound(g,1);
 if(homHP){*homHP=damage>=(int)*homHP?0:*homHP-damage;g->class50.homunHurtAt=g->time;if(!*homHP){g->class50.homunTarget=-1;combat_message(g,"Your Homunculus was defeated. Use Homunculus Resurrection.");}}
 else{s->hp-=damage;s->hurtAt=g->time;if(s->kind==5&&!s->triggered){s->triggered=1;s->next=g->time+5;}}
 return 1;
}
